type ParseResult<T> = { ok: true; node: T; next: number } | { ok: false };

function memoized<T>(impl: (pos: number) => ParseResult<T>): (pos: number) => ParseResult<T> {
  const cache = new Map<number, ParseResult<T>>();
  return (pos) => {
    const hit = cache.get(pos);
    if (hit !== undefined) return hit;      // failures are entries too
    const res = impl(pos);
    cache.set(pos, res);
    return res;
  };
}
